//! `docs/tools.md`: the tool reference, generated from the same definitions `tools/list`
//! sends, so it cannot drift from the server. `bedrock-mcp docs` prints it.

use std::fmt::Write;

use serde_json::Value;

use super::{REGISTRY, Tool, Toolset};
use crate::prompts::PROMPTS;

/// The reference as Markdown.
pub fn markdown() -> String {
    let mut out = String::from(
        "<!-- Generated by `cargo run -p bedrock-mcp -- docs > docs/tools.md`; do not edit. -->\n\n\
         # Tool reference\n\n\
         Every tool the server offers, grouped by toolset. `BEDROCK_MCP_TOOLSETS` (comma-separated \
         toolset names) limits the toolsets a client sees; without it every toolset is offered.\n\n",
    );
    out.push_str("| Toolset | Tool | What it does |\n| --- | --- | --- |\n");
    for toolset in Toolset::ALL {
        let tools = REGISTRY.iter().filter(|tool| tool.toolset == toolset);
        for (index, tool) in tools.enumerate() {
            // The toolset names its first row only, so each group reads as one block.
            let group = if index == 0 {
                format!("[{0}](#{0}-toolset)", toolset.name())
            } else {
                String::new()
            };
            let _ = writeln!(
                out,
                "| {group} | [`{0}`](#{0}) | {1} |",
                tool.name(),
                cell(tool.definition["title"].as_str().unwrap_or_default())
            );
        }
    }
    for toolset in Toolset::ALL {
        let _ = write!(
            out,
            "\n## {} toolset\n\n{}\n",
            toolset.name(),
            toolset.summary()
        );
        for tool in REGISTRY.iter().filter(|tool| tool.toolset == toolset) {
            tool_section(&mut out, tool);
        }
    }
    prompts_section(&mut out);
    out
}

/// The prompts `prompts/list` offers, with their arguments.
fn prompts_section(out: &mut String) {
    out.push_str(
        "\n## Prompts\n\nReady flows that name the exact tools and arguments for common jobs. A \
         client lists them with `prompts/list` and fills one in with `prompts/get`.\n",
    );
    for prompt in PROMPTS {
        let _ = write!(
            out,
            "\n### {}\n\n**{}**\n\n{}\n\n| Argument | Description |\n| --- | --- |\n",
            prompt.name, prompt.title, prompt.description
        );
        for argument in prompt.arguments {
            let flag = if argument.required() {
                " (required)"
            } else {
                ""
            };
            let _ = writeln!(
                out,
                "| `{}`{flag} | {} |",
                argument.name,
                cell(argument.description)
            );
        }
    }
}

fn tool_section(out: &mut String, tool: &Tool) {
    let definition = &tool.definition;
    let text = |key: &str| definition[key].as_str().unwrap_or_default().to_owned();
    let _ = write!(
        out,
        "\n### {}\n\n**{}** · {}\n\n{}\n",
        tool.name(),
        text("title"),
        behaviour(tool),
        text("description")
    );
    let schema = &definition["inputSchema"];
    let Some(properties) = schema["properties"]
        .as_object()
        .filter(|map| !map.is_empty())
    else {
        out.push_str("\nNo arguments.\n");
        return;
    };
    let required: Vec<&str> = schema["required"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect();
    let mut names: Vec<&String> = properties.keys().collect();
    names.sort_by_key(|name| (!required.contains(&name.as_str()), name.as_str()));
    out.push_str("\n| Argument | Type | Description |\n| --- | --- | --- |\n");
    for name in names {
        let property = &properties[name.as_str()];
        let flag = if required.contains(&name.as_str()) {
            " (required)"
        } else {
            ""
        };
        let _ = writeln!(
            out,
            "| `{name}`{flag} | {} | {} |",
            cell(&type_of(property)),
            cell(property["description"].as_str().unwrap_or_default())
        );
    }
}

/// What calling the tool does, from its hints.
fn behaviour(tool: &Tool) -> String {
    let hints = tool.hints;
    let mut parts = vec![
        match (hints.read_only, hints.destructive, hints.idempotent) {
            (true, _, _) => "reads only",
            (_, true, _) => "destructive",
            (_, _, true) => "sets state (repeating it changes nothing more)",
            _ => "acts (repeating it acts again)",
        },
    ];
    if hints.open_world {
        parts.push("may reach other machines");
    }
    parts.join(", ")
}

/// A short type for a property schema.
fn type_of(schema: &Value) -> String {
    if let Some(values) = schema["enum"].as_array() {
        return values
            .iter()
            .map(|value| format!("`{value}`"))
            .collect::<Vec<_>>()
            .join(" \\| ");
    }
    for key in ["oneOf", "anyOf"] {
        if let Some(options) = schema[key].as_array() {
            return options.iter().map(type_of).collect::<Vec<_>>().join(" or ");
        }
    }
    let kind = match &schema["type"] {
        Value::String(kind) => kind.clone(),
        Value::Array(kinds) => kinds
            .iter()
            .filter_map(Value::as_str)
            .collect::<Vec<_>>()
            .join(" or "),
        _ => return "any".into(),
    };
    let mut text = match kind.as_str() {
        "array" => format!("array of {}", type_of(&schema["items"])),
        "object" => match schema["properties"].as_object() {
            Some(fields) if !fields.is_empty() => {
                format!(
                    "object {{{}}}",
                    fields.keys().cloned().collect::<Vec<_>>().join(", ")
                )
            }
            _ => "object".into(),
        },
        _ => kind,
    };
    let bound = |key: &str| schema[key].as_f64().map(|value| value.to_string());
    match (
        bound("minimum").or(bound("exclusiveMinimum")),
        bound("maximum"),
    ) {
        (Some(low), Some(high)) => text.push_str(&format!(", {low} to {high}")),
        (Some(low), None) => text.push_str(&format!(", at least {low}")),
        (None, Some(high)) => text.push_str(&format!(", at most {high}")),
        (None, None) => {}
    }
    text
}

/// Text safe inside one Markdown table cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_committed_reference_matches_the_tools() {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/tools.md");
        let committed = std::fs::read_to_string(path).unwrap_or_default();
        assert!(
            committed == markdown(),
            "docs/tools.md is out of date; run `cargo run -p bedrock-mcp -- docs > docs/tools.md`."
        );
    }
}
